fn array_to_sequence(arr: &[bool; 10]) -> Vec<bool> {
    // Pre-allocate a Vec of length 10 to avoid reallocations.
    let mut res = Vec::with_capacity(10);
    // Copy each element from the fixed-size array into the Vec,
    // preserving order and value.
    for &value in arr.iter() {
        res.push(value);
    }
    res
}

